import {initialState} from './learning.js';
export const PROFILE_KEY='orbit-students-v1';
export function normalizeStudent(data={}){const fresh=initialState();for(const key of Object.keys(fresh)){if(Object.hasOwn(data,key)&&typeof data[key]===typeof fresh[key]&&data[key]!==null&&Array.isArray(data[key])===Array.isArray(fresh[key]))fresh[key]=data[key];}for(const key of['prediction','runtimeStats'])if(Object.hasOwn(data,key))fresh[key]=data[key];fresh.name=String(fresh.name).trim().slice(0,40)||'Student';fresh.planCompletions??={};fresh.annotations??={};fresh.markedForReview??=[];return fresh;}
export function loadRoster(storage,legacy){try{const raw=JSON.parse(storage.getItem(PROFILE_KEY));if(raw?.version===1&&Array.isArray(raw.students)&&raw.students.length&&raw.students.some(s=>s.id===raw.activeId))return{...raw,students:raw.students.map(s=>({...s,data:normalizeStudent(s.data)}))};}catch{}return{version:1,activeId:'self',students:[{id:'self',role:'owner',name:legacy.name,createdAt:Date.now(),data:normalizeStudent(legacy)}]};}
export function createStudent(roster,name,testDate=''){const clean=String(name).trim().slice(0,40);if(!clean)throw Error('Enter a student nickname.');const id=globalThis.crypto?.randomUUID?.()??`student-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;const data=normalizeStudent({...initialState(),name:clean,onboarded:true,testDate});const student={id,role:'student',name:clean,createdAt:Date.now(),data};roster.students.push(student);return student;}
export function saveRoster(storage,roster,state){const current=roster.students.find(s=>s.id===roster.activeId);if(!current)throw Error('Active profile missing');current.data=state;current.name=state.name;storage.setItem(PROFILE_KEY,JSON.stringify(roster));}
export function importStudent(roster,raw){const source=raw?.data??raw;if(!source||source.version!==1||!Array.isArray(source.log)||!Array.isArray(source.sessions)||!source.answers||typeof source.answers!=='object')throw Error('Choose an Orbit student export or progress JSON.');if(source.log.some(row=>!row||typeof row.id!=='string'||typeof row.correct!=='boolean'||!Number.isInteger(row.choice)||row.choice<0||row.choice>3))throw Error('This file contains invalid Orbit responses.');if(source.log.length>100000||source.sessions.length>10000)throw Error('This import is too large.');const student=createStudent(roster,source.name||'Imported student',source.testDate||'');student.data=normalizeStudent(source);return student;}
